export function validate(doc) {
  const issues = [];
  if (!doc.title.trim()) issues.push({ id: "title", sectionId: null, msg: "文档标题不能为空" });
  doc.sections.forEach((s, idx) => {
    const name = `第 ${idx + 1} 节`;
    if (!s.heading.trim()) issues.push({ sectionId: s.id, msg: `${name}「${SECTION_KINDS[s.kind].label}」缺少标题` });
    if (s.kind === "list" && s.items.some(it => !it.trim())) issues.push({ sectionId: s.id, msg: `${name}存在空条目` });
    if (s.kind === "facts" && s.pairs.some(p => !p.k.trim() || !p.v.trim())) issues.push({ sectionId: s.id, msg: `${name}存在未填写的键或值` });
    if (s.kind === "callout" && !s.note.trim()) issues.push({ sectionId: s.id, msg: `${name}说明内容为空` });
    if (s.kind === "text" && s.paragraphs.some(p => !p.trim())) issues.push({ sectionId: s.id, msg: `${name}存在空段落` });
  });
  return issues;
}
