import React, { useEffect, useMemo, useReducer, useRef, useState } from "react";
import {
  DOC_TYPES, SECTION_KINDS, STATUSES, initialDocument, reduceDoc, validate, stats, toMarkdown,
} from "./model.js";

const HISTORY_LIMIT = 100;

function historyReducer(state, action) {
  // undo/redo/reset-of-history handled here; doc ops flow through reduceDoc
  switch (action.t) {
    case "undo": { if (!state.past.length) return state; const past=[...state.past]; const doc=past.pop(); return { past, doc, future: [state.doc, ...state.future].slice(0,HISTORY_LIMIT) }; }
    case "redo": { if (!state.future.length) return state; const [doc,...rest]=state.future; return { past:[...state.past,state.doc].slice(-HISTORY_LIMIT), doc, future: rest }; }
    default: {
      const next = reduceDoc(state.doc, action);
      if (next === state.doc) return state; // guarded no-op: history untouched
      return { past: [...state.past, state.doc].slice(-HISTORY_LIMIT), doc: next, future: [] };
    }
  }
}
```

