export function reduceDoc(doc, a) {
  switch (a.t) {
    case "title": return { ...doc, title: a.v };
    case "meta": return { ...doc, meta: { ...doc.meta, [a.k]: a.v } };
    case "heading": return mapS(doc, a.id, (s) => ({ ...s, heading: a.v }));
    case "note": return mapS(doc, a.id, (s) => ({ ...s, note: a.v }));
    case "para": return mapS(doc, a.id, (s) => ({ ...s, paragraphs: s.paragraphs.map((p,i)=> i===a.i ? a.v : p) }));
    case "paraAdd": return mapS(doc, a.id, (s) => ({ ...s, paragraphs: [...s.paragraphs, ""] }));
    case "paraDel": return mapS(doc, a.id, (s) => s.paragraphs.length <= 1 ? s : ({ ...s, paragraphs: s.paragraphs.filter((_,i)=>i!==a.i) }));
    case "item"/"itemAdd"/"itemDel" similar with items
    case "pair": pairs.map((p,i)=> i===a.i ? {...p,[a.f]:a.v} : p)
    case "pairAdd": [...s.pairs, {k:"",v:""}]
    case "pairDel": guard len>1
    case "secAdd": { const sec = makeSection(a.kind); const arr=[...doc.sections]; arr.splice(clamp(a.at),0,sec); return {...doc, sections:arr}; }
    case "secDel": if (doc.sections.length<=1) return doc; return {...doc, sections: doc.sections.filter(s=>s.id!==a.id)};
    case "secMove": { const i=doc.sections.findIndex(s=>s.id===a.id); const j=i+a.dir; if(i<0||j<0||j>=len) return doc; swap; }
    case "reset": return initialDocument();
    default: return doc;
  }
}
```
