// 键盘可操作性度量：全程不使用鼠标，产生可核对的运行日志（measurement receipt）。
// 输出：evidence/keyboard-run.log + evidence/keyboard-run.json
import http from "node:http";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { mkdirSync } from "node:fs";
import puppeteer from "puppeteer-core";

const ROOT = path.resolve(import.meta.dirname, "..");
const DIST = path.join(ROOT, "dist");
const OUT = path.join(ROOT, "evidence");
const PORT = 4198;
const CHROME = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
mkdirSync(OUT, { recursive: true });

const log = [];
const say = (m) => {
  log.push(`[${new Date().toISOString()}] ${m}`);
  console.log(m);
};
const server = http
  .createServer(async (req, res) => {
    try {
      const data = await readFile(path.join(DIST, req.url.split("?")[0] === "/" ? "index.html" : req.url.slice(1)));
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      res.end(data);
    } catch {
      res.writeHead(404);
      res.end();
    }
  })
  .listen(PORT, "127.0.0.1");

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: true,
  defaultViewport: { width: 1600, height: 1000 },
  args: ["--no-first-run", "--disable-gpu"],
});
const page = await browser.newPage();
const outcomes = [];
const check = (id, cond, detail) => {
  outcomes.push({ id, pass: !!cond, detail });
  say(`${cond ? "PASS" : "FAIL"} ${id} — ${detail}`);
};

try {
  await page.goto(`http://127.0.0.1:${PORT}/`, { waitUntil: "load" });

  // 1) Tab 遍历：前 8 个停靠点全部是可交互元素且带 2px 可见焦点环
  const stops = [];
  for (let i = 0; i < 8; i++) {
    await page.keyboard.press("Tab");
    stops.push(
      await page.evaluate(() => {
        const el = document.activeElement;
        const cs = getComputedStyle(el);
        return {
          tag: el.tagName,
          label: el.getAttribute("aria-label") || el.textContent?.trim().slice(0, 10) || "",
          outline: `${cs.outlineStyle} ${cs.outlineWidth}`,
        };
      })
    );
  }
  say("tab stops: " + JSON.stringify(stops));
  check(
    "tab_traversal_focus_ring",
    stops.every((s) => ["BUTTON", "INPUT", "SELECT", "TEXTAREA"].includes(s.tag)) &&
      stops.every((s) => s.outline === "solid 2px"),
    "8/8 tab stops are interactive elements with 'solid 2px' focus ring"
  );

  // 2) 纯键盘编辑：Tab 到标题输入框 → Ctrl+A 全选 → 输入新标题 → 预览 h1 同步
  await page.evaluate(() => document.activeElement?.blur());
  let tabs = 0;
  let focused = "";
  while (tabs < 12) {
    await page.keyboard.press("Tab");
    tabs++;
    focused = await page.evaluate(() => document.activeElement?.getAttribute("aria-label") || "");
    if (focused === "文档标题") break;
  }
  check("keyboard_reach_title", focused === "文档标题", `title input reached after ${tabs} Tabs`);
  await page.keyboard.down("Control");
  await page.keyboard.press("a");
  await page.keyboard.up("Control");
  await page.keyboard.type("Aurora 笔记 2.5 更新说明");
  await new Promise((r) => setTimeout(r, 120));
  const h1 = await page.evaluate(() => document.querySelector(".paper h1")?.textContent.trim());
  check("keyboard_edit_updates_preview", h1 === "Aurora 笔记 2.5 更新说明", `preview h1 after keyboard typing = "${h1}"`);

  // 3) Ctrl+Z 撤销 → 预览恢复
  await page.keyboard.down("Control");
  await page.keyboard.press("z");
  await page.keyboard.up("Control");
  await new Promise((r) => setTimeout(r, 120));
  const h1b = await page.evaluate(() => document.querySelector(".paper h1")?.textContent.trim());
  check("keyboard_undo_restores", h1b === "Aurora 笔记 2.4 更新说明", `preview h1 after Ctrl+Z = "${h1b}"`);

  // 4) 键盘选中预览块：Tab 至 .pv-sec → Enter 触发双向选择
  await page.evaluate(() => document.activeElement?.blur());
  let found = -1;
  for (let i = 0; i < 60; i++) {
    await page.keyboard.press("Tab");
    const isPv = await page.evaluate(() => document.activeElement?.classList.contains("pv-sec") || false);
    if (isPv) {
      found = i + 1;
      break;
    }
  }
  const pvLabel = await page.evaluate(() => document.activeElement?.getAttribute("aria-label") || "");
  await page.keyboard.press("Enter");
  await new Promise((r) => setTimeout(r, 200));
  const sel = await page.evaluate(() => {
    const id = document.activeElement.dataset.section;
    return {
      pv: document.activeElement.classList.contains("selected"),
      card: document.querySelector(`.sec-card[data-section="${id}"]`)?.classList.contains("selected"),
    };
  });
  check(
    "keyboard_select_preview_block",
    found > 0 && sel.pv && sel.card,
    `Tab reached preview block in ${found} stops ("${pvLabel}"); Enter selected both panes (pv=${sel.pv}, editor card=${sel.card})`
  );

  // 5) 键盘重做：Ctrl+Y 恢复刚才的撤销（标题回到 2.5）
  await page.keyboard.down("Control");
  await page.keyboard.press("y");
  await page.keyboard.up("Control");
  await new Promise((r) => setTimeout(r, 120));
  const h1c = await page.evaluate(() => document.querySelector(".paper h1")?.textContent.trim());
  check("keyboard_redo", h1c === "Aurora 笔记 2.5 更新说明", `preview h1 after Ctrl+Y = "${h1c}"`);
} finally {
  await browser.close();
  server.close();
}

const passed = outcomes.filter((o) => o.pass).length;
say(`SUMMARY: ${passed}/${outcomes.length} keyboard checks passed`);
await writeFile(path.join(OUT, "keyboard-run.log"), log.join("\n") + "\n");
await writeFile(path.join(OUT, "keyboard-run.json"), JSON.stringify(outcomes, null, 2));
process.exit(passed === outcomes.length ? 0 : 1);

