const HISTORY_LIMIT = 100;

// 历史栈包住结构 reducer：每个落盘操作都可撤销（MC-5，P-28）。
function historyReducer(state, action) {
  switch (action.t) {
    case "undo": {
      if (!state.past.length) return state;
      const past = state.past.slice(0, -1);
      const doc = state.past[state.past.length - 1];
      return { past, doc, future: [state.doc, ...state.future].slice(0, HISTORY_LIMIT) };
    }
    case "redo": {
      if (!state.future.length) return state;
      const [doc, ...rest] = state.future;
      return { past: [...state.past, state.doc].slice(-HISTORY_LIMIT), doc, future: rest };
    }
    default: {
      const next = reduceDoc(state.doc, action);
      if (next === state.doc) return state; // guard 拒绝的操作：历史不推进
      return {
        past: [...state.past, state.doc].slice(-HISTORY_LIMIT),
        doc: next,
        future: [],
      };
    }
  }
}

const initState = () => ({ past: [], doc: initialDocument(), future: [] });

